internal class GUPPriceEngineRelatedDataObject
{
    private Common data;

    // Key = AttributeName + AttributeTypeName, value = UPSPriceEngineEcoResValueObject (includes value and dataType).
    private Map ecoResAttributeMap;

}

Method.Source:
public void new (Common _data, Map _ecoResAttributeMap = null)
{
    this.data = _data;
    this.ecoResAttributeMap = _ecoResAttributeMap;
}

public boolean isEcoResAttribute()
{
    return this.data == null;
}

    public str getValueByEcoResAttributeKey(str _attributeName, str _attributeTypeName)
    {
        if (!this.isEcoResAttribute())
        {
            Error("Wrong method call as this is not an EcoResAttribute.");
        }

        str ret;
        str attributeKey = GUPPricingAttributeEcoResAttribute::createAttributeKey(_attributeName, _attributeTypeName);

        if (this.ecoResAttributeMap.exists(attributeKey))
        {
            ret = this.ecoResAttributeMap.lookup(GUPPricingAttributeEcoResAttribute::createAttributeKey(_attributeName, _attributeTypeName)).parmValue();
        }

        return ret;
    }
